function createCounter(initialCount) {
  let state = { count: initialCount || 0 };

  function getState() {
    return state;
  }

  function setState(newState) {
    state = newState;
  }

  // BUG: captures `state` once, when the handler is created, instead of
  // reading the latest state on every call - a classic stale-closure bug.
  function makeIncrementHandler() {
    const capturedState = state;
    return function increment() {
      setState({ count: capturedState.count + 1 });
    };
  }

  return { getState, setState, makeIncrementHandler };
}

module.exports = { createCounter };

test_setup_files.test_stale_closure.js:
const assert = require('assert');
const { createCounter } = require('./counter.js');

const c = createCounter(0);
const increment = c.makeIncrementHandler();
increment();
increment();
increment();
assert.strictEqual(c.getState().count, 3, `expected 3 increments to raise count by 3, got ${c.getState().count}`);

increment();
increment();
assert.strictEqual(c.getState().count, 5, `expected count 5 after 5 total increments, got ${c.getState().count}`);

const c2 = createCounter(10);
const inc2a = c2.makeIncrementHandler();
inc2a();
const inc2b = c2.makeIncrementHandler();
inc2b();
inc2a();
assert.strictEqual(c2.getState().count, 13, `expected count 13 (10 + 3 increments across handler instances), got ${c2.getState().count}`);

console.log('PASS');
